Object.assign(paths,{menu:'M3 6h18M3 12h18M3 18h18',rod:'M4 21 18 3m-6 9 3 3m-5-1 3 3M18 3h3v12a4 4 0 0 1-8 0',waves:'M2 9c3-5 5 5 8 0s5 5 8 0 4 0 4 0M2 16c3-5 5 5 8 0s5 5 8 0 4 0 4 0',boat:'M3 13h18l-4 7H7l-4-7Zm9-10v10m0-10 7 7h-7M2 22c3-3 5 3 8 0s5 3 8 0 4 0 4 0',hook:'M12 2v12a5 5 0 1 1-10 0v-2l4 3m2-9h8',reel:'M17 11a6 6 0 1 1-12 0 6 6 0 0 1 12 0Zm-6 0h.01M11 5V2h5m1 9h4v7h-4M5 16l-3 6m9-5v5',line:'M3 6h18M3 18h18M6 6v12m12-12v12M6 9h12M6 12h12M6 15h12',pin:'M19 10c0 6-7 12-7 12S5 16 5 10a7 7 0 1 1 14 0Zm-4 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',back:'M20 12H4m6-6-6 6 6 6',card:'M2 5h20v14H2zM2 10h20M6 15h3'});
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`}
function icons(root=document){$$('[data-icon]',root).forEach(x=>x.innerHTML=icon(x.dataset.icon))}
function load(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
let DATA,products,toastTimer,state={favorites:load('op-favorites',[]),cart:load('op-cart',{}),compare:[],homeTab:'selected',demoOrder:null};
let checkoutDraft={name:'',phone:'',city:'',district:'',address:'',sameInvoice:true};
const techniques=[['LRF','Hafif takımla kıyı avı','fish'],['Spin','At–çek avcılığı','rod'],['Surf','Kıyıdan uzağa atış','waves'],['Jigging','Dikey avcılık','hook'],['Trolling','Tekne ilerlerken av','boat'],['Yemli','Doğal yemle av','hook'],['Sazan avı','Göl ve tatlı su','fish'],['Tekne avı','Tekneden avcılık','boat']];
const equipment=[['Olta Makineleri','Makine','reel'],['Olta Kamışları','Kamış','rod'],['Yapay Yemler','Yem','fish'],['İp ve Misina','İp & misina','line'],['Hazır Setler','Hazır set','box'],['Diğer Ekipmanlar','Diğer ekipmanlar','grid']];
function route(name,params={}){let entries=params instanceof URLSearchParams?[...params]:Object.entries(params),q=new URLSearchParams(entries.filter(([,v])=>v!==''&&v!=null)).toString();return '#'+name+(q?'?'+q:'')}
function external(url,label,cls=''){let href=typeof localHref==='function'?localHref(url,String(label).replace(/<[^>]*>/g,'')):url;if(href?.startsWith('#'))label=label.replaceAll(icon('upRight'),icon('arrow')).replace(/ ↗/g,'');return `<a class="${cls}" href="${esc(href)}">${label}</a>`}
function current(){let raw=location.hash.slice(1)||'home',i=raw.indexOf('?');return {name:i<0?raw:raw.slice(0,i),params:new URLSearchParams(i<0?'':raw.slice(i+1))}}
function go(name,params={}){navigationByClick=true;scrollPositions.set(location.hash,window.scrollY);let h=route(name,params);if(location.hash===h)render(true,true);else location.hash=h}
function persist(){try{localStorage.setItem('op-favorites',JSON.stringify(state.favorites));localStorage.setItem('op-cart',JSON.stringify(state.cart))}catch{toast('Bu oturumda kullanabilirsin; tarayıcın seçimlerini kaydetmiyor.')}}
function toast(text,link=''){let t=$('#toast');t.innerHTML=esc(text)+(link?` <a href="${link}">Sepetimi aç →</a>`:'');t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4500)}
function updateCounts(){$$('.cart-count').forEach(x=>x.textContent=Object.values(state.cart).reduce((a,b)=>a+b,0))}
function favorite(slug){let i=state.favorites.indexOf(slug);if(i>=0)state.favorites.splice(i,1);else state.favorites.push(slug);persist();$$('[data-favorite]').filter(x=>x.dataset.favorite===slug).forEach(b=>{let on=state.favorites.includes(slug);b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on);b.setAttribute('aria-label',on?'Favorilerimden çıkar':'Favorilerime ekle');b.setAttribute('title',on?'Favorilerimden çıkar':'Favorilerime ekle');if(b.closest('.secondary-actions'))b.innerHTML=icon('heart')+(on?'Favorilerimden çıkar':'Favorilerime ekle')});toast(i>=0?'Favorilerinden çıkarıldı.':'Favorilerine eklendi.');if(current().params.has('favorites'))render(false)}
function addCart(slug,notify=true,selection=[]){let p=products.find(p=>p.slug===slug);if(!p||p.paymentMode!=='online'){toast('Bu ilanda alışveriş için satıcıyla görüşmelisin.');return false}if(p.stockStatus!=='in'){toast(p.stockStatus==='out'?'Bu ürün şu anda stokta yok.':'Stok bilgisini satıcıdan doğrulamalısın.');return false}if(!Array.isArray(selection)||selection.length!==(p.variants?.length||0)||selection.some(x=>!Array.isArray(x)||x.length!==2||x.some(v=>typeof v!=='string'))||(p.variants?.length&&p.variants.some((v,i)=>!selection[i]||selection[i][0]!==v.label||!v.options.some(o=>o.label===selection[i][1])))){toast('Ürünün seçeneklerini belirleyerek devam et.');return false}let total=Object.entries(state.cart).filter(([key])=>key.split('::')[0]===slug).reduce((sum,[,q])=>sum+q,0);if(total>=(p.maxQty||99)){toast('Bu üründen en fazla '+(p.maxQty||99)+' adet seçebilirsin.');return false}let key=selection.length?slug+'::'+encodeURIComponent(JSON.stringify(selection)):slug;state.cart[key]=(state.cart[key]||0)+1;persist();updateCounts();if(notify)toast('Ürün sepetine eklendi.','#cart');return true}
function modeLabel(p){return p.paymentMode==='online'?'Siteden satın al':p.paymentMode==='contact'?'Satıcıyla görüş':'Satış biçimini kontrol et'}
function pageShell(title,html,description=''){return `<div class="wrap page">${breadcrumb(title)}${heading(title,description)}${html}</div>`}
function sectionHead(title,desc,link,label='Tümünü gör'){return `<div class="section-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${link?`<a class="text-link" href="${link}">${label}${icon('arrow')}</a>`:''}</div>`}
function breadcrumb(label){return `<nav class="breadcrumb" aria-label="Sayfa yolu"><a href="#home">Ana sayfa</a>${icon('chevron')}<span>${esc(label)}</span></nav>`}
function heading(title,desc){return `<div class="page-heading"><h1>${esc(title)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div>`}
function empty(title,desc,action='Ürünleri keşfet',href='#catalog'){return `<div class="empty">${icon('search')}<h2>${esc(title)}</h2><p>${esc(desc)}</p><a class="button" href="${esc(href)}">${esc(action)}${icon('arrow')}</a></div>`}
function storePage(){return `<div class="wrap">${breadcrumb('Mağazalar & markalar')}${heading('Balıkçılığın ortak adresleri.','Mağazaları tanı, ürünlerine göz at.')}<div class="store-grid">${DATA.stores.map(s=>external(s.url,`<span class="seller-avatar">${esc(s.name[0])}</span><div><h2>${esc(s.name)}</h2><p>Mağazayı ziyaret et</p></div>${icon('upRight')}`,'store-card')).join('')}</div>${sectionHead('Sevdiğin markaları bul','Aradığın markaya dokun, ürünlerine bak.')}<div class="services">${[...new Set(products.map(p=>p.brand))].filter(b=>b!=='Belirtilmemiş').sort((a,b)=>a.localeCompare(b,'tr')).map(b=>`<a class="service-link" href="${route('catalog',{brand:b})}">${esc(b)}${icon('arrow')}</a>`).join('')}</div>${external(BASE+'/markalar','Tüm markaları gör '+icon('upRight'),'button outline')}<div class="section"></div></div>`}
function sellPage(){return `<div class="wrap">${breadcrumb('Ürün sat')}${heading('Satmak mı istiyorsun? Buradan başla.','Sana uygun satış yolunu seç.')}<div class="cards-grid"><article class="info-card">${icon('user')}<div class="eyebrow">BİREYSEL SATICI</div><h2>Kendi ekipmanımı satacağım.</h2><p>Bir mağazan yoksa da ürününü ekleyebilirsin. Hesabına gir, ürün bilgilerini ve fotoğraflarını ekle.</p>${external(BASE+'/hesabim?ilan&pID=0','Ürünümü ekle '+icon('arrow'),'button')}</article><article class="info-card">${icon('store')}<div class="eyebrow">MAĞAZA SAHİBİ</div><h2>Mağazamı açacağım.</h2><p>İşletmenin ürünlerini balıkçılarla buluştur. Mağaza başvurusuyla satış sürecine başla.</p>${external(BASE+'/magaza/magaza-kayitol','Mağaza aç '+icon('arrow'),'button')}</article><article class="info-card">${icon('box')}<div class="eyebrow">MEVCUT SATICI</div><h2>Zaten mağazam var.</h2><p>Ürün, ilan, sipariş, kargo, ödeme ve hesap özeti işlemlerini satıcı panelinden yönet.</p>${external(BASE+'/magaza/magaza-giris','Satıcı paneline gir '+icon('arrow'),'button')}</article></div><section class="selling-banner"><span>${icon('help')}</span><div><h2>Nereden başlayacağını bilmiyor musun?</h2><p>Ekibimize yaz, sana yardımcı olalım.</p></div>${external('https://wa.me/+905405441515','WhatsApp’tan sor '+icon('chat'),'button')}</section></div>`}
function toolsPage(){const names=['Gemi Trafiği','Rüzgâr & Dalga','Deniz Tahmini','Deniz Sıcaklığı','Marina & Barınaklar','NAVTEX Uyarıları','Av Yasakları'];return `<div class="wrap">${breadcrumb('Balıkçı araçları')}${heading('Avdan önce bir kontrol et.','Hava, deniz, güvenlik ve kargo araçlarına tek yerden ulaş.')}<div class="cards-grid">${names.map((n,i)=>{let l=DATA.links.find(l=>l.title===n);return l?`<article class="info-card">${icon(i===1?'wind':'compass')}<h2>${n}</h2><p>İlgili kaynağın güncel bilgilerini incele.</p>${external(l.url,'Kaynağı aç '+icon('upRight'),'text-link')}</article>`:''}).join('')}</div><section class="tool-calculator"><h2>Kargo desisi hesapla</h2><p class="dialog-intro">Paketin ölçülerini santimetre olarak gir. Formül: en × boy × yükseklik ÷ 3000. Kargonun uyguladığı ücret değişebilir.</p><form id="desi-form"><div class="calculator-inputs">${['En','Boy','Yükseklik'].map((t,i)=>`<label class="field"><span>${t} (cm)</span><input type="number" name="d${i}" min="0.1" max="10000" step="any" required inputmode="decimal" placeholder="Örn. 30"></label>`).join('')}</div><button class="button small" type="submit">Hesapla ${icon('arrow')}</button></form><div id="desi-output" role="status"></div></section></div>`}
function directoryPage(){return `<div class="wrap">${breadcrumb('Tüm sayfalar & hizmetler')}${heading('Aradığın her şey burada.','Kategori, hesap, mağaza ve destek alanlarının tamamını burada bulabilirsin.')}<label class="field services-search"><span>Sayfa ya da kategori ara</span><input type="search" id="directory-search" placeholder="Örn. kamp, kupon, kargo, LRF…"></label><p class="directory-note" id="directory-count">${DATA.links.length} bağlantı</p><div class="services" id="directory-results">${directoryLinks(DATA.links)}</div></div>`}
function directoryLinks(links){if(!links.length)return empty('Bu isimde bir sayfa yok.','Farklı bir kelimeyle aramayı dene.','Tüm ürünlere bak','#catalog');let groups={'Kategoriler ve ekipmanlar':[],'Hesap ve satıcı işlemleri':[],'Mağazalar ve markalar':[],'Yardım ve kurumsal bilgiler':[],'Balıkçı araçları, uygulamalar ve topluluk':[],'Ürün sayfaları':[]};let slugs=new Set(products.map(p=>p.slug));const help=/destek|sikca|iletisim|hakkimizda|politika|sozlesme|metni|yasakli|sitemap|fatura-islemleri|kargo-olusturma|siparis-yonetimi|magaza-acma|desi-hesaplama/;for(let l of links){let u=new URL(l.url),path=u.pathname.slice(1);let g=slugs.has(path)?'Ürün sayfaları':/^(hesabim|magaza\/|giris|kayitol|cikis|satici-ol)/.test(path)?'Hesap ve satıcı işlemleri':help.test(path)?'Yardım ve kurumsal bilgiler':u.hostname!=='www.oltapazari.com.tr'||/blog|rehberi|teklif/.test(path)?'Balıkçı araçları, uygulamalar ve topluluk':/markalar|magazalar/.test(path)||DATA.stores.some(x=>x.url===l.url)?'Mağazalar ve markalar':'Kategoriler ve ekipmanlar';groups[g].push(l)}return Object.entries(groups).filter(([,ls])=>ls.length).map(([name,ls],i)=>`<details class="directory-group" ${i===0||links.length<DATA.links.length?'open':''}><summary>${name}<span>${ls.length} bağlantı</span></summary><div class="directory-group-links">${ls.map(l=>external(l.url,esc(l.title)+icon('upRight'),'service-link')).join('')}</div></details>`).join('')}
function productCard(p){let special=(p.kind==='listing'||p.paymentMode!=='online')&&p.stockStatus!=='out',needs=p.variants?.length,cta=p.stockStatus==='out'?'<button class="button card-buy" disabled>Stokta yok</button>':p.paymentMode==='online'&&p.stockStatus!=='in'?`<a class="button outline card-buy" href="${route('contact',{id:p.slug})}">Stok bilgisini sor ${icon('chat')}</a>`:p.paymentMode==='online'?needs?`<a class="button card-buy" href="${route('product',{id:p.slug})}">Seçenekleri seç ${icon('arrow')}</a>`:`<button class="button card-buy" data-card-add="${esc(p.slug)}" aria-label="${esc(p.name)} ürününü sepete ekle">${icon('bag')}Sepete ekle</button>`:`<a class="button outline card-buy" href="${route('contact',{id:p.slug})}">${p.paymentMode==='contact'?'Satıcıyla görüş':'Satıcıya sor'} ${icon('chat')}</a>`;return `<article class="product-card simple-product"><button type="button" class="favorite card-favorite ${state.favorites.includes(p.slug)?'selected':''}" data-favorite="${esc(p.slug)}" aria-pressed="${state.favorites.includes(p.slug)}" aria-label="${state.favorites.includes(p.slug)?'Favorilerimden çıkar':'Favorilerime ekle'}" title="${state.favorites.includes(p.slug)?'Favorilerimden çıkar':'Favorilerime ekle'}">${icon('heart')}</button>${p.oldPrice&&p.oldPrice>p.price?`<span class="simple-discount">%${Math.round((1-p.price/p.oldPrice)*100)} indirim</span>`:''}<a class="product-image" href="${route('product',{id:p.slug})}"><img src="${p.image}" alt="${esc(p.name)}" width="300" height="300" loading="lazy"></a><div class="product-info"><h3 class="product-title"><a href="${route('product',{id:p.slug})}">${esc(p.name)}</a></h3><a class="card-seller" href="${route('store',{id:p.sellerPath||p.seller})}" aria-label="${esc(p.seller)} satıcısının ürünleri">${esc(p.seller)}</a><div class="price-row"><div>${p.oldPrice&&p.oldPrice>p.price?`<span class="old-price">${money(p.oldPrice)}</span>`:''}<span class="price">${money(p.price)}</span></div></div>${special?`<div class="payment-label ${p.paymentMode==='online'?'online':'contact'}">${p.paymentMode==='online'&&p.stockStatus!=='in'?'Stok bilgisi doğrulanmalı':modeLabel(p)}</div>`:''}${cta}</div></article>`}
function disciplineTiles(){const names=['lrf','spin','surf','jigging','trolling','yemli','sazan','tekne'];return techniques.map(([t,d],i)=>`<a class="discipline-card photo-card" href="${route('discipline',{name:t})}"><div class="discipline-photo">${DATA.disciplineImages?.[names[i]]?`<img src="${DATA.disciplineImages[names[i]]}" alt="${esc(d)}" width="600" height="400" loading="${i<4?'eager':'lazy'}">`:''}</div><div class="discipline-card-copy"><h3>${t}</h3><p>${d}</p><span>${icon('arrow')}</span></div></a>`).join('')}
function homeFeatured(){let found=[];if(state.homeTab==='listing')return products.filter(p=>p.kind==='listing').slice(0,4);if(state.homeTab==='deals')return products.filter(p=>p.oldPrice).slice(0,4);for(let fn of [p=>p.slug==='shimano-stradic-sw-8000pg-olta-makinesi',p=>p.category==='Olta Kamışları'&&p.paymentMode==='online',p=>p.category==='Yapay Yemler'&&p.paymentMode==='online',p=>p.category==='Hazır Setler'&&p.paymentMode==='online']){let p=products.find(fn);if(p)found.push(p)}return found}
