let HOMEPAGE=JSON.parse(JSON.stringify(DEFAULT_HOMEPAGE));
function homepageLink(value,fallback){if(typeof value!=='string'||value.length>1200||/[\u0000-\u0020<>"'`]/.test(value))return fallback;if(/^#[a-z][a-z0-9-]*(?:\?[^#]*)?$/i.test(value))return value;try{let u=new URL(value);if(u.protocol==='https:'&&u.hostname&&!u.username&&!u.password)return u.href}catch{}return fallback}
function homepageImage(value,fallback){if(typeof value!=='string'||value.length>300||!/^assets\/(?:[a-zA-Z0-9_-]+\/)*[a-zA-Z0-9_-][a-zA-Z0-9_.-]*\.(?:png|webp|jpe?g|avif|svg)$/i.test(value)||value.includes('..'))return fallback;return value}
function sanitizeHomepage(raw){const d=JSON.parse(JSON.stringify(DEFAULT_HOMEPAGE)),object=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{},text=(v,f,max=300)=>typeof v==='string'&&v.trim()&&v.length<=max?v.trim():f,action=(v,f)=>{v=object(v);return {label:text(v.label,f.label,80),href:homepageLink(v.href,f.href)}},section=(v,f)=>{v=object(v);return {...f,title:text(v.title,f.title,160),description:text(v.description,f.description,500),action:action(v.action,f.action)}};if(!raw||typeof raw!=='object'||Array.isArray(raw)||raw.version!==1)return d;let h=object(raw.hero);d.hero={eyebrow:text(h.eyebrow,d.hero.eyebrow,100),title:text(h.title,d.hero.title,160),description:text(h.description,d.hero.description,500),primaryAction:action(h.primaryAction,d.hero.primaryAction),secondaryAction:action(h.secondaryAction,d.hero.secondaryAction),image:homepageImage(h.image,d.hero.image),imageAlt:typeof h.imageAlt==='string'&&h.imageAlt.length<=200?h.imageAlt:d.hero.imageAlt,caption:text(h.caption,d.hero.caption,160)};let c=object(raw.categories);d.categories.title=text(c.title,d.categories.title,160);d.categories.action=action(c.action,d.categories.action);if(Array.isArray(c.items)&&c.items.length===6)d.categories.items=c.items.map((v,i)=>{v=object(v);let f=d.categories.items[i];return {label:text(v.label,f.label,80),href:homepageLink(v.href,f.href),image:homepageImage(v.image,f.image),imageFrame:['contain','rod-detail','line-spool'].includes(v.imageFrame)?v.imageFrame:f.imageFrame,imageAlt:typeof v.imageAlt==='string'&&v.imageAlt.length<=200?v.imageAlt:f.imageAlt}});for(let key of ['deals','featured']){let v=object(raw[key]),f=d[key];d[key]=section(v,f);if(key==='deals')d[key].eyebrow=text(v.eyebrow,f.eyebrow,100);d[key].productSlugs=Array.isArray(v.productSlugs)&&v.productSlugs.length<=12&&v.productSlugs.every(s=>typeof s==='string'&&/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(s)&&s.length<=300)?[...new Set(v.productSlugs)]:f.productSlugs}if(Array.isArray(raw.paths)&&raw.paths.length===2)d.paths=raw.paths.map((v,i)=>{v=object(v);let f=d.paths[i];return {title:text(v.title,f.title,160),description:text(v.description,f.description,500),href:homepageLink(v.href,f.href),icon:['compass','user','fish','rod','boat','box','store'].includes(v.icon)?v.icon:f.icon}});for(let key of ['request','assistance'])d[key]=section(raw[key],d[key]);return d}
function loadHomepageConfig(){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),4000);return fetch('homepage.json?v=20261107-1',{signal:controller.signal}).then(r=>{if(!r.ok)throw Error('homepage');return r.json()}).then(raw=>{HOMEPAGE=sanitizeHomepage(raw)}).catch(()=>{HOMEPAGE=sanitizeHomepage(null)}).finally(()=>clearTimeout(timeout))}
function homepageProducts(slugs,list){let selected=slugs.map(slug=>list.find(p=>p.slug===slug)).filter(Boolean);return selected.length?selected:list.slice(0,4)}
function home(){const c=HOMEPAGE,available=products.filter(p=>p.stockStatus==='in'&&p.paymentMode==='online'),deals=homepageProducts(c.deals.productSlugs,available.filter(p=>p.oldPrice>p.price)),picks=homepageProducts(c.featured.productSlugs,available.filter(p=>p.kind==='store')),lines=value=>esc(value).replace(/\\n|\r\n?|\n/g,' <br>'),action=(a,cls='text-link')=>`<a class="${cls}" href="${esc(a.href)}">${esc(a.label)} ${icon('arrow')}</a>`,shortcuts=c.categories.items.map(item=>`<a class="shop-category" href="${esc(item.href)}"><span class="shop-category-media ${item.imageFrame}"><img src="${esc(item.image)}" alt="${esc(item.imageAlt)}" width="120" height="120" loading="lazy"></span><span>${esc(item.label)}</span>${icon('arrow')}</a>`).join('');return `<div class="wrap shop-home"><section class="shop-welcome" aria-labelledby="welcome-title"><div class="shop-welcome-copy"><span class="shop-eyebrow">${esc(c.hero.eyebrow)}</span><h1 id="welcome-title">${lines(c.hero.title)}</h1><p>${lines(c.hero.description)}</p><div class="shop-welcome-actions">${action(c.hero.primaryAction,'button')}${action(c.hero.secondaryAction)}</div></div><div class="shop-welcome-visual"><img src="${esc(c.hero.image)}" alt="${esc(c.hero.imageAlt)}" width="720" height="720" fetchpriority="high"><span>${esc(c.hero.caption)}</span></div></section><section class="shop-categories" aria-labelledby="quick-categories-title"><div class="section-head"><div><h2 id="quick-categories-title">${esc(c.categories.title)}</h2></div>${action(c.categories.action)}</div><div class="shop-category-grid">${shortcuts}</div></section>${deals.length?`<section class="section home-deals"><div class="section-head"><div><span class="section-kicker">${esc(c.deals.eyebrow)}</span><h2>${esc(c.deals.title)}</h2><p>${esc(c.deals.description)}</p></div>${action(c.deals.action)}</div><div class="product-grid deal-grid">${deals.map(productCard).join('')}</div></section>`:''}${picks.length?`<section class="section home-store"><div class="section-head"><div><h2>${esc(c.featured.title)}</h2><p>${esc(c.featured.description)}</p></div>${action(c.featured.action)}</div><div class="product-grid">${picks.map(productCard).join('')}</div></section>`:''}<section class="shop-paths" aria-label="Alışverişe devam et">${c.paths.map(item=>`<a href="${esc(item.href)}"><span class="path-icon">${icon(item.icon)}</span><div><h2>${esc(item.title)}</h2><p>${esc(item.description)}</p></div>${icon('arrow')}</a>`).join('')}</section><section class="request-banner"><span>${icon('box')}</span><div><h2>${esc(c.request.title)}</h2><p>${esc(c.request.description)}</p></div>${action(c.request.action,'button outline')}</section><div class="home-assistance"><div><h2>${esc(c.assistance.title)}</h2><p>${esc(c.assistance.description)}</p></div>${action(c.assistance.action,'button')}</div></div>`}
function techniquesPage(){return pageShell('Av türleri',`<nav class="category-mode-tabs" aria-label="Kategori seçimi"><a href="#categories">Ekipmana göre</a><a href="#techniques" aria-current="page">Av türüne göre</a></nav><a class="simple-help" href="#finder">Kararsızım, yardımcı ol ${icon('arrow')}</a><div class="discipline-grid">${disciplineTiles()}</div><div class="section-end"><a class="text-link" href="#directory">Diğer tüm kategoriler ${icon('arrow')}</a></div>`,'Av türüne dokun. Sonraki ekranda ekipmanını seç.')}
function disciplinePage(params){let name=params.get('name')||'Spin',t=techniques.find(x=>x[0]===name);if(!t)return techniquesPage();let list=products.filter(p=>(p.disciplines||[]).includes(name)),categories=equipment.filter(([c])=>list.some(p=>p.category===c));return pageShell(name+' için ne arıyorsun?',`<a class="text-link change-discipline" href="#techniques">${icon('back')}Av türünü değiştir</a><div class="equipment-grid simple-equipment">${categories.map(([c,n])=>{let p=list.find(p=>p.category===c);return `<a class="equipment-card" href="${route('catalog',{discipline:name,category:c})}"><img src="${p.image}" alt="" width="220" height="150"><h2>${n}</h2>${icon('arrow')}</a>`}).join('')||`<div class="notice"><strong>Bu kategoride ${esc(name)} ürünü yok.</strong>Farklı bir kategori seçebilirsin.</div>`}</div><div class="section-end"><a class="button outline" href="${route('catalog',{discipline:name})}">Tüm ${esc(name)} ürünlerini gör ${icon('arrow')}</a></div><details class="source-categories"><summary>İlgili kategoriler</summary><div class="services">${(DATA.disciplineSources?.[name]||[]).map(([u,c])=>external(BASE+'/'+u,esc(c)+icon('upRight'),'service-link')).join('')}</div></details>`,'İhtiyacın olan ekipmana dokun.')}
function listingPage(){let online=products.filter(p=>p.kind==='listing'&&p.paymentMode==='online'),contact=products.filter(p=>p.kind==='listing'&&p.paymentMode==='contact');return pageShell('Bireysel ilanlar',`<div class="listing-choice-grid"><a class="listing-choice" href="#catalog?kind=listing&mode=online"><span>${icon('bag')}</span><h2>Siteden satın al</h2><p>Bu ürünlerde alışveriş ve ödeme site üzerinden yapılabilir.</p><strong>${online.length} ürün ${icon('arrow')}</strong></a><a class="listing-choice contact-choice" href="#catalog?kind=listing&mode=contact"><span>${icon('chat')}</span><h2>Satıcıyla görüş</h2><p>Bu ilanlarda online ödeme yok. Bilgi ve alışveriş için satıcıyla iletişime geç.</p><strong>${contact.length} ilan ${icon('arrow')}</strong></a></div><section class="section">${sectionHead('Balıkçılardan yeni bir hikâyeye','Her ilanda satış biçimi açıkça belirtilir.','#catalog?kind=listing','Tüm bireysel ilanlar')}<div class="product-grid">${[...online.slice(0,2),...contact.slice(0,2)].map(productCard).join('')}</div></section><div class="notice"><strong>Bireysel ilan her zaman ikinci el demek değildir.</strong>Ürünün durumunu açıklamasından kontrol et; gerektiğinde satıcıya sor.</div><div class="section-end"><a class="text-link" href="#sell">Sen de ürününü satmak mı istiyorsun? ${icon('arrow')}</a></div>`,'Mağaza olmadan satış yapan balıkçılara ulaş. İstersen online satın al, istersen satıcıyla görüş.')}
function productDetail(params){let p=products.find(p=>p.slug===params.get('id'));if(!p)return pageShell('Ürün bulunamadı',empty('Bu ürünü bulamadık.','Kataloğa dönüp başka bir ürüne bakabilirsin.'));let online=p.paymentMode==='online',saved=state.favorites.includes(p.slug);return `<div class="wrap page simple-detail">${breadcrumb(p.category)}<div class="product-detail"><div class="detail-image"><img src="${p.image}" alt="${esc(p.name)}" width="600" height="600"></div><section class="detail-info"><h1>${esc(p.name)}</h1><div class="detail-price">${p.oldPrice>p.price?`<span class="old-price">${money(p.oldPrice)}</span>`:''}<strong>${money(p.price)}</strong></div>${p.stockStatus==='out'?'<p class="stock-status out">Stokta yok</p>':p.stockStatus==='in'?'<p class="stock-status in">Stokta</p>':'<p class="stock-status">Stok bilgisi doğrulanmalı</p>'}<p class="simple-seller">Satıcı: <a href="${route('catalog',{q:p.seller})}">${esc(p.seller)}</a></p>${p.kind==='listing'||!online?`<div class="simple-sale-mode"><strong>${p.stockStatus==='out'?'Stok bilgisi':modeLabel(p)}</strong>${!online?`<p>${p.stockStatus==='out'?'Ürünün yeniden ne zaman geleceğini satıcıya sorabilirsin.':'Bu ilanda satın almak için satıcıyla görüşmelisin.'}</p>`:''}</div>`:''}<div class="detail-buttons">${online&&p.stockStatus!=='in'&&p.stockStatus!=='out'?`<a class="button" href="${route('contact',{id:p.slug})}">Stok bilgisini sor ${icon('chat')}</a>`:online?`${p.stockStatus==='out'?`<button class="button" disabled>Stokta yok</button><a class="text-link" href="${route('catalog',{category:p.category,stock:'1'})}">Stoktaki benzer ürünleri gör ${icon('arrow')}</a>`:`<button class="button" data-add="${esc(p.slug)}">Sepete ekle ${icon('arrow')}</button>`}`:external(route('contact',{id:p.slug}),(p.paymentMode==='contact'?'Satıcıyla iletişime geç':'Satıcıya sor')+' '+icon('upRight'),'button full')}</div><details class="secondary-actions"><summary>Karşılaştır ve paylaş</summary><label class="compare-check"><input type="checkbox" data-compare="${esc(p.slug)}" ${state.compare.includes(p.slug)?'checked':''}>Karşılaştırmaya ekle</label>${online&&p.stockStatus==='in'?`<button class="text-link" data-buy="${esc(p.slug)}">Hemen al ${icon('arrow')}</button>`:''}</details></section></div><div class="detail-sections"><details open><summary>Ürün bilgileri</summary><div class="specs">${[['Marka',p.brand],['Kategori',p.category],['Satıcı',p.seller],['Alışveriş biçimi',modeLabel(p)],...(p.specs||[])].map(([k,v])=>`<div class="spec-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>${(p.description||[]).map(x=>`<p>${esc(x)}</p>`).join('')}</details><details><summary>Teslimat ve iade bilgileri</summary><p>Teslimat süresi, kargo bedeli ve iade koşulları satıcıya ve ürüne göre değişebilir.</p>${external(BASE+'/iptal-ve-iade-politikasi','İade koşullarını oku ↗','text-link')}</details><details><summary>Satıcıya sor ve yorumları gör</summary><p>Ürünün durumunu veya merak ettiğin detayları satıcıya sor.</p><a class="button outline" href="${route('contact',{id:p.slug})}">Satıcıya soru sor ${icon('arrow')}</a></details></div></div>`}
function contactPage(params){let p=products.find(p=>p.slug===params.get('id'));if(!p)return helpPage();return pageShell('Satıcıya soru sor',`<form id="seller-question" class="contact-panel"><div class="mini-product"><img src="${p.image}" alt="${esc(p.name)}" width="110" height="110"><div><h2>${esc(p.name)}</h2><p>${esc(p.seller)}</p></div></div><label class="field"><span>Mesajın</span><textarea name="message" rows="5" required placeholder="Ürün hakkında ne öğrenmek istiyorsun?"></textarea></label><button class="button full" type="submit">Mesajı gönder ${icon('arrow')}</button><p class="form-note" id="question-result" role="status"></p></form>`)}

function guidePage(){return pageShell('Balıkçılık rehberi',`<a class="help-banner" href="#finder">${icon('compass')}<span><strong>İlk takımını birlikte bulalım.</strong><small>İki soru. Teknik bilgi gerektirmez.</small></span>${icon('arrow')}</a><div class="guide-grid">${DATA.links.filter(l=>l.title.length>45&&/rehberi|farklar|karşılaştır|tehlike/i.test(l.title)).filter((x,i,a)=>a.findIndex(y=>y.url===x.url)===i).slice(0,4).map((l,i)=>external(l.url,`<div class="article-visual">${icon(['book','reel','fish','compass'][i])}<span>Olta rehberi</span></div><div class="article-body"><h2>${esc(l.title)}</h2><strong>Yazıyı oku ${icon('arrow')}</strong></div>`,'article-card')).join('')}</div><div class="section-end">${external(BASE+'/blog','Tüm rehber yazılarını gör '+icon('upRight'),'button outline')}</div>`,'Teknik terimleri ve ekipman seçeneklerini sade anlatımlarla tanı.')}
function helpPage(){return pageShell('Nasıl yardımcı olabiliriz?',`<div class="help-contact">${external('https://wa.me/+905405441515',icon('chat')+'WhatsApp’tan yaz','button')}<a class="button outline" href="tel:+905405441515">${icon('phone')}Bizi ara</a><a class="button outline" href="mailto:info@oltapazari.com.tr">E-posta gönder</a></div><section class="faq">${[['Nasıl sipariş veririm?','Ürünü aç ve Sepete ekle’ye dokun. Sepetinde Teslimata devam et ile adresini seç. Son ekranda ürünlerini ve bilgilerini kontrol ederek siparişi tamamla.'],['Bireysel ilanlarda ödeme nasıl çalışıyor?','Siteden satın al etiketi olan ürünler sepete eklenebilir. Satıcıyla görüş etiketli ilanlarda online ödeme yoktur; satıcıya mesaj gönderebilirsin.'],['Ürün seçmekte zorlanıyorum.','Ana sayfadaki Seçmeme yardım et bağlantısına veya Menü’de Ekipman seçmeme yardım et’e dokun. İki kısa soruyla sana uygun başlangıç noktasını bulabilirsin.'],['Siparişlerimi nerede görebilirim?','Hesabım sayfasından Siparişlerim bölümüne ulaşabilirsin.'],['Favorilerime nasıl ürün eklerim?','Ürün kartının sağ üstündeki kalbe dokun. Dolu kalp ürünün favorilerine eklendiğini gösterir. Favorilerine Hesabım’dan ulaşabilirsin.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><div class="section-end"><a class="button outline" href="#directory">Tüm destek konuları ${icon('arrow')}</a></div>`,'Sorunun yanıtını bul ya da Olta Pazarı ekibine ulaş.')}

function accountPage(){let items=[['hesabim?aldiklarim','Sipariş ve iadeler','Siparişlerini takip et.','box'],['hesabim?favorilerim','Favorilerim','Beğendiğin ürünleri gör.','heart'],['hesabim?kuponlarim','Kuponlarım','Hesabına tanımlı kuponlar.','bag'],['hesabim?bilgilerim#userAddress','Adreslerim','Teslimat adreslerini düzenle.','pin'],['hesabim?bilgilerim','Hesap ayarlarım','Kişisel bilgilerini yönet.','sliders'],['hesabim?ilanlarim','Ürün ve ilanlarım','Bireysel satışlarını yönet.','grid']];return pageShell('Hesabım',`<section class="account-welcome"><span>${icon('user')}</span><div><h2>Hesabım</h2><p>Siparişlerini ve hesap bilgilerini buradan yönet.</p></div><div>${external(BASE+'/giris','Giriş yap','button')}${external(BASE+'/kayitol','Kayıt ol','button outline')}</div></section><div class="account-grid">${items.map(([u,n,d,i])=>external(u.includes('aldiklarim')?'#orders':u.includes('favorilerim')?'#catalog?favorites=1':BASE+'/'+u,icon(i)+`<span><strong>${n}</strong><small>${d}</small></span>`+icon('chevron'),'account-link')).join('')}</div><section class="section">${sectionHead('Seçimlerin','Beğendiğin ve seçtiğin ürünlere kolayca ulaş.')}<div class="quick-grid"><a class="quick-link" href="#cart">${icon('bag')}<strong>Sepetim</strong><span class="cart-count">0</span></a><a class="quick-link" href="#catalog?favorites=1">${icon('heart')}<strong>Favorilerim</strong><span>${state.favorites.length}</span></a><a class="quick-link" href="#compare">${icon('compare')}<strong>Karşılaştırma</strong><span>${state.compare.length}</span></a></div></section><section class="section">${sectionHead('Satış işlemleri','Bireysel ürün ekle veya mağazanı yönet.')}<div class="quick-grid"><a class="quick-link" href="#sell">${icon('plus')}<strong>Ürün sat / mağaza aç</strong>${icon('chevron')}</a>${external(BASE+'/magaza/magaza-giris',icon('store')+'<strong>Satıcı paneli</strong>'+icon('upRight'),'quick-link')}${external(BASE+'/hesabim?ilan&pID=0',icon('plus')+'<strong>Bireysel ilan ekle</strong>'+icon('upRight'),'quick-link')}</div></section>`)}
function menuPage(){let groups=[['Alışveriş',[['categories','Kategoriler','grid'],['catalog','Tüm ürünler','grid'],['techniques','Av türleri','compass'],['listings','Bireysel ilanlar','user'],['catalog?deal=1','İndirimli ürünler','bag'],['stores','Mağazalar ve markalar','store']]],['Hesabım',[['cart','Sepetim','bag'],['catalog?favorites=1','Favorilerim','heart'],['compare','Karşılaştırma','compare'],['account','Hesabım ve siparişlerim','user']]],['Yardım ve keşif',[['finder','Ekipman seçmeme yardım et','compass'],['guide','Balıkçılık rehberi','book'],['tools','Hava, deniz ve balıkçı araçları','wind'],['help','Yardım ve iletişim','help'],['directory','Tüm kategoriler ve hizmetler','grid']]],['Diğer',[['sell','Ürün sat / mağaza aç','store'],['settings','Dil ve para birimi','sliders'],['request','Yurt dışından ürün iste','box'],['apps','Mobil uygulamalar','grid']]]];return pageShell('Nereye gitmek istersin?',`<div class="menu-grid">${groups.map(([t,ls])=>`<section class="menu-group"><h2>${t}</h2>${ls.map(([u,n,i])=>`<a href="#${u}">${icon(i)}<span>${n}</span>${icon('chevron')}</a>`).join('')}</section>`).join('')}</div>`,'Alışveriş, hesap ve destek alanlarına buradan ulaş.')}
function cartItems(){return Object.entries(state.cart).map(([key,q])=>{let [slug,raw]=key.split('::'),options=[];try{options=raw?JSON.parse(decodeURIComponent(raw)):[]}catch{}return {p:products.find(p=>p.slug===slug),q,key,options}}).filter(x=>x.p&&x.p.paymentMode==='online')}
function cartTotal(){return cartItems().reduce((s,{p,q})=>s+p.price*q,0)}
function orderSummary(button='',note=true){let list=cartItems();return `<aside class="order-summary"><h2>Sipariş özeti</h2><div class="summary-line"><span>${list.reduce((s,x)=>s+x.q,0)} ürün</span><strong>${money(cartTotal())}</strong></div><div class="summary-line"><span>Kargo ücreti</span><span>Henüz hesaplanmadı</span></div><div class="summary-total"><span>Ürün toplamı</span><strong>${money(cartTotal())}</strong></div>${button}${note?'<p class="summary-note">Devam etmeden önce ürünlerini ve teslimat bilgilerini kontrol et.</p>':''}<a class="summary-help" href="#help">${icon('help')}Yardıma ihtiyacım var</a></aside>`}
function cartPage(){let list=cartItems();if(!list.length)return pageShell('Sepetim',empty('Sepetin henüz boş.','Beğendiğin üründe Sepete ekle’ye dokun. Satıcıyla görüşülen ilanlar sepete eklenmez.'));return pageShell('Sepetim',`<div class="checkout-steps"><strong><span>1</span>Sepet</strong><span><i>2</i>Teslimat</span><span><i>3</i>Kontrol</span></div><div class="cart-layout"><section><div class="cart-products">${list.map(({p,q,key,options})=>`<article class="cart-item"><a href="${route('product',{id:p.slug})}"><img src="${p.image}" alt="${esc(p.name)}" width="110" height="110"></a><div class="cart-product-info"><p>${esc(p.seller)}</p>${options.length?`<p class="cart-options">${options.map(([k,v])=>esc(k)+': '+esc(v)).join(' · ')}</p>`:''}<h2><a href="${route('product',{id:p.slug})}">${esc(p.name)}</a></h2><strong>${money(p.price)}</strong>${p.stockStatus!=='in'?'<p class="stock-status out">'+(p.stockStatus==='out'?'Stokta yok':'Stok bilgisi doğrulanmalı')+'</p>':''}<div class="quantity"><button data-qty="${esc(key)}" data-delta="-1" ${q<=1?'disabled':''} aria-label="${esc(p.name)} adedini azalt">${icon('minus')}</button><span aria-live="polite">${q}</span><button data-qty="${esc(key)}" data-delta="1" ${p.stockStatus!=='in'||list.filter(x=>x.p.slug===p.slug).reduce((n,x)=>n+x.q,0)>=(p.maxQty||99)?'disabled':''} aria-label="${esc(p.name)} adedini artır">${icon('plus')}</button></div></div><button class="remove-item" data-delete="${esc(key)}" aria-label="${esc(p.name)} ürününü sepetten çıkar">${icon('trash')}<span>Çıkar</span></button></article>`).join('')}</div><a href="#catalog" class="text-link continue-shopping">${icon('back')}Alışverişe devam et</a></section>${orderSummary(list.some(x=>x.p.stockStatus!=='in')?'<button class="button full" disabled>Stok bilgisi eksik ürünü çıkar</button>':'<a class="button full" href="#checkout?step=address">Teslimata devam et '+icon('arrow')+'</a>')}</div>`,'Ürünlerini kontrol et, teslimata devam et.')}
function checkoutSteps(active){return `<nav class="checkout-steps" aria-label="Sipariş adımları"><a href="#cart"><span>1</span>Sepet</a><a href="#checkout?step=address" ${active==='address'?'aria-current="step"':''}><span>2</span>Teslimat</a><span class="${active==='review'?'active':''}"><i>3</i>Kontrol</span></nav>`}
function addressField(name,label,autocomplete,type='text'){return `<label class="field"><span id="checkout-label-${name}">${esc(label)}</span><input name="${name}" type="${type}" autocomplete="${autocomplete}" value="${esc(checkoutDraft[name])}" aria-labelledby="checkout-label-${name}" aria-describedby="error-${name}" required><small id="error-${name}" class="field-error"></small></label>`}
function checkoutPage(params){if(cartItems().some(x=>x.p.stockStatus!=='in'))return cartPage();if(!cartItems().length)return cartPage();let step=params.get('step')==='review'?'review':'address';if(step==='review'&&Object.keys(addressErrors(checkoutDraft)).length)step='address';if(step==='review')return pageShell('Son bir kontrol',`${checkoutSteps('review')}<div class="cart-layout"><section><div class="checkout-panel"><div class="panel-title"><h2>Teslimat adresi</h2><a href="#checkout?step=address">Değiştir</a></div><p><strong>${esc(checkoutDraft.name)}</strong><br>${esc(checkoutDraft.address)}<br>${esc(checkoutDraft.district)} / ${esc(checkoutDraft.city)}<br>${esc(checkoutDraft.phone)}</p></div>${!checkoutDraft.sameInvoice?`<div class="checkout-panel"><div class="panel-title"><h2>Fatura adresi</h2><a href="#checkout?step=address">Değiştir</a></div><p><strong>${esc(checkoutDraft.billingName)}</strong><br>${esc(checkoutDraft.billingAddress)}</p></div>`:''}<div class="checkout-panel"><h2>Ödeme</h2><div class="demo-payment">${icon('card')}<div><strong>Bu önizlemede ödeme alınmaz</strong><p>Kart bilgisi istenmez ve gerçek sipariş oluşturulmaz.</p></div></div></div><div class="checkout-panel"><h2>Ürünlerin</h2>${cartItems().map(({p,q,options})=>`<div class="review-product"><img src="${p.image}" alt="" width="64" height="64"><span><strong>${esc(p.name)}</strong><small>${q} adet${options.length?' · '+options.map(([k,v])=>esc(k)+': '+esc(v)).join(' · '):''}</small></span><b>${money(p.price*q)}</b></div>`).join('')}</div></section>${orderSummary('<button class="button full" data-action="place-demo">Denemeyi tamamla '+icon('arrow')+'</button>')}</div>`);return pageShell('Nereye teslim edilsin?',`${checkoutSteps('address')}<p class="notice checkout-preview-note"><strong>Alışveriş akışı önizlemesi.</strong> Gerçek sipariş veya ödeme oluşturulmaz. Adımları örnek bilgilerle deneyebilirsin.</p><div class="cart-layout"><form id="address-form" class="checkout-panel" novalidate><div class="panel-title"><h2>Teslimat bilgileri</h2></div><div class="address-grid">${addressField('name','Ad soyad','name')}${addressField('phone','Telefon','tel','tel')}${addressField('city','İl','address-level1')}${addressField('district','İlçe','address-level2')}<label class="field address-full"><span id="checkout-label-address">Açık adres</span><textarea name="address" rows="3" autocomplete="street-address" aria-labelledby="checkout-label-address" aria-describedby="error-address" required>${esc(checkoutDraft.address)}</textarea><small id="error-address" class="field-error"></small></label></div><label class="radio-field"><input type="checkbox" name="sameInvoice" ${checkoutDraft.sameInvoice?'checked':''}>Fatura adresim de aynı</label><div id="invoice-fields">${checkoutDraft.sameInvoice?'':billingFields()}</div><button class="button full" type="submit">Siparişi kontrol et ${icon('arrow')}</button></form>${orderSummary('',false)}</div>`)}
function orderPage(){let o=state.demoOrder;if(!o)return pageShell('Siparişlerim',empty('Henüz siparişin yok.','Ürünlere göz atarak alışverişe başlayabilirsin.'));return pageShell('Sipariş adımlarını tamamladın.',`<section class="order-success"><span class="success-check">${icon('check')}</span><h2>Teşekkürler.</h2><p>Bu denemede ödeme alınmadı ve gerçek sipariş oluşturulmadı.</p><div class="demo-number">${esc(o.id)}</div><div class="summary-line"><span>${o.qty} ürün</span><strong>${money(o.total)}</strong></div><div class="success-actions"><a class="button" href="#catalog">Alışverişe devam et ${icon('arrow')}</a><a class="button outline" href="#orders">Siparişlerim</a></div></section>`)}
function ordersPage(){let o=state.demoOrder;return pageShell('Siparişlerim',o?`<div class="checkout-panel"><h2>${esc(o.id)}</h2><p>${o.qty} ürün · ${money(o.total)}</p><p>Deneme akışı tamamlandı. Ödeme alınmadı.</p><a class="button outline" href="#order">Ayrıntıları gör ${icon('arrow')}</a></div>`:empty('Henüz siparişin yok.','Ürünlere göz atarak alışverişe başlayabilirsin.'))}

function comparePage(){let ps=state.compare.map(s=>products.find(p=>p.slug===s)).filter(Boolean);if(ps.length<2)return pageShell('Ürünleri karşılaştır',empty('En az iki ürün seç.','Ürün detayında Karşılaştır ve paylaş alanını aç. En az iki, en fazla üç ürün seçebilirsin.'));return pageShell('Ürünleri karşılaştır',`<div class="compare-scroll"><table class="compare-table"><thead><tr><th>Ürün</th>${ps.map(p=>`<th><a href="${route('product',{id:p.slug})}"><img src="${p.image}" alt="${esc(p.name)}" width="180" height="160">${esc(p.name)}</a></th>`).join('')}</tr></thead><tbody>${[['Fiyat',p=>money(p.price)],['Kategori',p=>p.category],['Marka',p=>p.brand],['Satıcı',p=>p.seller],['Alışveriş biçimi',p=>modeLabel(p)],['Stok',p=>p.stockStatus==='in'?'Stokta':p.stockStatus==='out'?'Stokta yok':'Belirtilmemiş']].map(([k,fn])=>`<tr><th scope="row">${k}</th>${ps.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}<tr><th>İncele</th>${ps.map(p=>`<td><a class="button small" href="${route('product',{id:p.slug})}">Ürüne bak</a><button class="text-link" data-uncompare="${esc(p.slug)}">Çıkar</button></td>`).join('')}</tr></tbody></table></div><p class="snapshot-note">Teknik özellikleri ve ürün durumunu satın almadan önce kontrol et.</p>`,'Seçeneklerini yan yana gör. Karar verirken hatırlamak zorunda kalma.')}
function finderPage(params){let place=params.get('place'),level=params.get('level');if(!['shore','boat','fresh','unsure'].includes(place))place='';if(!['beginner','experienced'].includes(level))level='';if(!place)return pageShell('Birlikte bulalım.',`<div class="finder-card"><div class="step-kicker">1 / 2 · Av yerin</div><h2>Nerede balık tutacaksın?</h2><p>En yakın seçeneği işaretle.</p><div class="finder-options">${[['shore','Kıyıdan','Sahil, iskele veya kayalık','waves'],['boat','Tekneden','Tekneyle denizde','boat'],['fresh','Göl veya akarsuda','Tatlı suda','fish'],['unsure','Henüz bilmiyorum','Yeni başlıyorum','compass']].map(([v,n,d,i])=>`<a href="${route('finder',{place:v})}">${icon(i)}<span><strong>${n}</strong><small>${d}</small></span>${icon('chevron')}</a>`).join('')}</div></div>`,'Teknik bilgi gerektirmeyen iki basit soru.');if(!level)return pageShell('Nasıl başlamak istersin?',`<a class="text-link" href="#finder">${icon('back')}Av yerini değiştir</a><div class="finder-card"><div class="step-kicker">2 / 2 · Deneyimin</div><h2>Sana en uygun seçenek hangisi?</h2><div class="finder-options">${[['beginner','Yeni başlıyorum','Hazır setlerle kolayca başlayayım.','box'],['experienced','Takımımı geliştireceğim','İhtiyacım olan parçayı seçeyim.','reel']].map(([v,n,d,i])=>`<a href="${route('finder',{place,level:v})}">${icon(i)}<span><strong>${n}</strong><small>${d}</small></span>${icon('chevron')}</a>`).join('')}</div></div>`);let recommendation=finderRecommendation(place,level);return pageShell('Başlangıç noktan hazır.',`<div class="finder-result"><span class="success-check">${icon('compass')}</span><h2>${recommendation.title}</h2><p>${recommendation.description}</p><a class="button" href="${recommendation.href}">${recommendation.label} ${icon('arrow')}</a><a class="button outline" href="#finder">Baştan seç</a></div>`)}
function settingsPage(){return pageShell('Dil ve para birimi',`<div class="settings-card"><h2>Dil seçenekleri</h2><p>Türkçe, Arapça, İspanyolca, İngilizce, Almanca, Fransızca, Japonca ve Rusça.</p><p>TL, USD, EUR, GBP ve CNY para birimleri seçenekleri kullanılabilir.</p>${external(BASE+'/','Tercihleri değiştir '+icon('upRight'),'button')}</div>`,'Dil ve para birimi tercihlerini yönet.')}
function appsPage(){let ls=DATA.links.filter(l=>/apps.apple.com|play.google.com/.test(l.url));return pageShell('Olta Pazarı cebinde.',`<div class="settings-card"><h2>Resmi uygulamayı indir.</h2><div class="help-contact">${ls.slice(0,2).map(l=>external(l.url,l.url.includes('apple')?'App Store ↗':'Google Play ↗','button')).join('')}</div></div>`)}
function footer(){return `<div class="wrap shop-footer"><div class="footer-brand"><a class="brand" href="#home"><img src="${DATA.logo}" alt="Olta Pazarı" width="190" height="34"></a><p>Balıkçılık için ihtiyacın olan her şey,<br>anlaşılır ve kolay bir alışveriş deneyimi.</p><a class="text-link" href="#help">Yardıma mı ihtiyacın var? ${icon('arrow')}</a></div><nav aria-label="Alışveriş bağlantıları"><h2>Alışveriş</h2><a href="#categories">Kategoriler</a><a href="#brands">Markalar</a><a href="#stores">Mağazalar</a><a href="#listings">Bireysel ilanlar</a></nav><nav aria-label="Destek bağlantıları"><h2>Yanındayız</h2><a href="#help">Yardım merkezi</a><a href="#guide">Olta rehberi</a><a href="#request">Yurt dışından ürün iste</a><a href="#sell">Satıcı ol</a></nav><div class="footer-bottom"><p>© 2026 Olta Pazarı</p><nav aria-label="Bilgi bağlantıları"><a href="#directory">Tüm hizmetler</a><a href="#info?path=gizlilik-politikasi&title=Gizlilik">Gizlilik</a><a href="#info?path=iptal-ve-iade-politikasi&title=İptal%20ve%20iade">İptal ve iade</a></nav><span class="preview-caption">Tasarım önizlemesi · Gerçek sipariş alınmaz.</span></div></div>`}
let scrollPositions=new Map(),navigationByClick=false;
function updateCompareTray(){let prev=$('#compare-tray');if(prev)prev.remove();let inline=$('#compare-inline');if(inline)inline.remove();if(!state.compare.length||current().name!=='product')return;let area=$('.secondary-actions');if(!area)return;let a=document.createElement('a');a.id='compare-inline';a.className='button outline';a.href='#compare';a.innerHTML=state.compare.length>=2?state.compare.length+' ürünü karşılaştır '+icon('compare'):'Seçili ürünü gör (1 / 3) '+icon('arrow');area.append(a)}
function compare(slug,on){if(on&&state.compare.length>=3&&!state.compare.includes(slug)){toast('En fazla 3 ürünü yan yana karşılaştırabilirsin.');$$('[data-compare]').filter(x=>x.dataset.compare===slug).forEach(x=>x.checked=false);return}if(on&&!state.compare.includes(slug))state.compare.push(slug);if(!on)state.compare=state.compare.filter(s=>s!==slug);$$('[data-compare]').filter(x=>x.dataset.compare===slug).forEach(x=>x.checked=on);try{localStorage.setItem('op-compare',JSON.stringify(state.compare))}catch{}updateCompareTray()}
function render(restore=true,forceTop=false){if(!DATA)return;let {name,params}=current();document.body.classList.toggle('checkout-mode',['checkout','order'].includes(name));const pages={home,catalog:()=>catalog(params),techniques:techniquesPage,discipline:()=>disciplinePage(params),product:()=>enhancedProduct(params),listings:listingPage,stores:localStores,sell:sellPage,tools:toolsPage,directory:directoryPage,guide:guidePage,help:helpPage,account:accountPage,menu:menuPage,cart:cartPage,checkout:()=>checkoutPage(params),order:orderPage,orders:ordersPage,filters:()=>filtersPage(params),compare:usableCompare,finder:()=>finderPage(params),settings:settingsPage,apps:appsPage,contact:()=>usefulContact(params),categories:categoriesScreen,category:()=>categoryScreen(params),store:()=>sellerScreen(params),brands:brandsScreen,gallery:()=>galleryScreen(params),info:()=>infoScreen(params),newsletter:newsletterScreen};accountRoutes.forEach(n=>pages[n]=()=>accountScreen(n,params));$('#main').innerHTML=(pages[name]||(()=>pageShell('Sayfa bulunamadı',empty('Bu sayfayı bulamadık.','Ana sayfadan tekrar başlayabilirsin.','Ana sayfaya dön','#home'))))();document.title=name==='home'?'Olta Pazarı | Balıkçılık ekipmanları':($('#main h1')?.textContent||'Olta Pazarı')+' | Olta Pazarı';$('#search-input').value=name==='catalog'?(params.get('q')||''):'';$$('[data-nav]').forEach(a=>{let active=(a.dataset.nav===name&&!(name==='catalog'&&(params.has('deal')||params.has('favorites')||params.get('kind')==='listing')))||(a.dataset.nav==='categories'&&['categories','category'].includes(name))||(a.dataset.nav==='favorites'&&params.has('favorites'))||(a.dataset.nav==='deals'&&params.has('deal'))||(a.dataset.nav==='techniques'&&name==='discipline')||(a.dataset.nav==='listings'&&params.get('kind')==='listing');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$$('[data-mobile]').forEach(a=>{let active=a.dataset.mobile===name||(a.dataset.mobile==='account'&&(accountRoutes.includes(name)||['orders','order'].includes(name)))||(a.dataset.mobile==='favorites'&&params.has('favorites'))||(a.dataset.mobile==='categories'&&['category','discipline','catalog','listings','techniques','product','gallery','store','stores','brands'].includes(name)&&!params.has('favorites'));a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});updateMenuControl(name);if(typeof localHref==='function')$$('a[href]',document).forEach(a=>{let href=a.getAttribute('href');if(href&&href.includes('oltapazari.com.tr'))a.setAttribute('href',localHref(href,a.textContent.trim()))});updateCounts();updateCompareTray();if(name==='filters')updateFilterPreview();if(restore){let y=forceTop?0:(scrollPositions.get(location.hash)||0);$('#main').focus({preventScroll:true});requestAnimationFrame(()=>window.scrollTo({top:y,behavior:'instant'}))}}
function placeDemo(){if(cartItems().some(x=>x.p.stockStatus!=='in')){toast('Stokta olmayan veya stok bilgisi doğrulanmamış ürünü sepetinden çıkar.');go('cart');return}if(!cartItems().length){go('cart');return}if(Object.keys(addressErrors(checkoutDraft)).length){go('checkout',{step:'address'});toast('Önce teslimat bilgilerini tamamla.');return}state.demoOrder={id:'DENEME-'+Date.now().toString().slice(-7),qty:cartItems().reduce((s,x)=>s+x.q,0),total:cartTotal()};try{localStorage.setItem('op-demo-order',JSON.stringify(state.demoOrder))}catch{}state.cart={};persist();updateCounts();go('order')}
function addressErrors(data){let errors={},phone=(data.phone||'').trim(),digits=phone.replace(/\D/g,'');if((data.name||'').trim().length<2)errors.name='Adını ve soyadını yaz.';if(digits.length<10||digits.length>15||!/^[+\d\s().-]+$/.test(phone))errors.phone='Geçerli bir telefon numarası yaz (10–15 hane).';if(!(data.city||'').trim())errors.city='İl bilgisini yaz.';if(!(data.district||'').trim())errors.district='İlçe bilgisini yaz.';if((data.address||'').trim().length<10)errors.address='Adresini biraz daha ayrıntılı yaz.';if(!data.sameInvoice){if(!(data.billingName||'').trim())errors.billingName='Fatura adı veya ünvanını yaz.';if((data.billingAddress||'').trim().length<10)errors.billingAddress='Fatura adresini yaz.'}return errors}
function captureAddress(form){let fd=Object.fromEntries(new FormData(form));checkoutDraft={...checkoutDraft,...fd,sameInvoice:!!fd.sameInvoice};return checkoutDraft}
function saveAddress(form){let data=captureAddress(form),errors=addressErrors(data);for(let k of ['name','phone','city','district','address',...(!data.sameInvoice?['billingName','billingAddress']:[])]){let input=form.elements[k],err=$('#error-'+k,form);if(err)err.textContent=errors[k]||'';if(input)input.setAttribute('aria-invalid',errors[k]?'true':'false')}let first=Object.keys(errors)[0];if(first){form.elements[first].focus();return false}return true}
const actions={'retry-catalog':()=>loadCatalog(),account:()=>go('account'),categories:()=>go('categories'),cart:()=>go('cart'),favorites:()=>go('catalog',{favorites:'1'}),filters:()=>openFilters(current().params),wizard:()=>go('finder'),comparison:()=>go('compare'),'clear-compare':()=>{state.compare=[];$$('[data-compare]').forEach(x=>x.checked=false);try{localStorage.setItem('op-compare','[]')}catch{}updateCompareTray()},'place-demo':placeDemo,preferences:()=>go('settings'),apps:()=>go('apps')};
document.addEventListener('click',e=>{let a=e.target.closest('a[href^="#"]');if(a){scrollPositions.set(location.hash,window.scrollY);navigationByClick=true;if(a.getAttribute('href')===location.hash&&!a.classList.contains('skip')){e.preventDefault();window.scrollTo({top:0,behavior:'instant'});navigationByClick=false;return}}if(a?.classList.contains('skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}let el=e.target.closest('[data-action],[data-favorite],[data-add],[data-buy],[data-home-tab],[data-remove-filter],[data-qty],[data-delete],[data-uncompare],[data-price-min]');if(!el)return;if(el.hasAttribute('data-price-min')){let form=el.closest('form');form.elements.min.value=el.dataset.priceMin;form.elements.max.value=el.dataset.priceMax;updateFilterPreview();return}if(el.dataset.action){actions[el.dataset.action]?.();return}if(el.dataset.favorite){favorite(el.dataset.favorite);return}if(el.dataset.add){let p=products.find(p=>p.slug===el.dataset.add);if(p&&p.paymentMode==='online'&&p.stockStatus!=='out'&&(state.cart[p.slug]||0)>=(p.maxQty||99)){go('cart');toast('Bu ürün zaten sepetinde.');return}if(addCart(el.dataset.add,false))go('cart');return}if(el.dataset.buy){let p=products.find(p=>p.slug===el.dataset.buy);if(p&&p.paymentMode==='online'&&p.stockStatus!=='out'&&state.cart[p.slug]){go('checkout',{step:'address'});return}if(addCart(el.dataset.buy,false))go('checkout',{step:'address'});return}if(el.dataset.homeTab){state.homeTab=el.dataset.homeTab;$$('[data-home-tab]').forEach(x=>{x.classList.toggle('active',x===el);x.setAttribute('aria-pressed',x===el)});$('#home-products').innerHTML=homeFeatured().map(productCard).join('');return}if(el.dataset.removeFilter){let context=current(),params=catalogParams(context.params,context.name),key=el.dataset.removeFilter;if(key==='brand'&&el.dataset.filterValue){let brands=values(params,'brand').filter(v=>normalize(v)!==normalize(el.dataset.filterValue));if(brands.length)params.set('brand',brands.join(','));else params.delete('brand')}else params.delete(key);params.delete('page');goCatalog(params);return}if(el.dataset.qty){let s=el.dataset.qty;let p=products.find(p=>p.slug===s.split('::')[0]);let other=Object.entries(state.cart).filter(([k])=>k!==s&&k.split('::')[0]===p?.slug).reduce((n,[,q])=>n+q,0);state.cart[s]=Math.max(1,Math.min((p?.maxQty||99)-other,(state.cart[s]||0)+Number(el.dataset.delta)));persist();render(false);$$('[data-qty]').find(x=>x.dataset.qty===s&&x.dataset.delta===el.dataset.delta)?.focus();return}if(el.dataset.delete){delete state.cart[el.dataset.delete];persist();render(false);($('[data-delete]')||$('.continue-shopping')||$('#main'))?.focus();toast('Ürün sepetinden çıkarıldı.');return}if(el.dataset.uncompare){compare(el.dataset.uncompare,false);render(false)}});
document.addEventListener('change',e=>{if(e.target.closest('#address-form'))captureAddress(e.target.closest('form'));if(e.target.closest('.refined-filters'))updateFilterPreview();if(e.target.matches('[data-compare]'))compare(e.target.dataset.compare,e.target.checked);if(e.target.id==='sort'){let context=current(),params=catalogParams(context.params,context.name);params.set('sort',e.target.value);params.delete('page');goCatalog(params)}if(e.target.name==='sameInvoice')$('#invoice-fields').innerHTML=e.target.checked?'':billingFields()});
