function sortKey(params){let v=params.get('sort');return ['recommended','bestselling','most-viewed','newest','price-asc','price-desc','discount-desc','name'].includes(v)?v:'recommended'}

function finderRecommendation(place,level){if(place==='unsure')return {title:'Önce av türlerini tanıyalım.',description:'Her av türünün kısa açıklamasına bak. Nerede ve nasıl avlanmak istediğine göre ekipmanını seçebilirsin.',href:'#techniques',label:'Av türlerini gör'};let dis=place==='boat'?'Tekne avı':place==='fresh'?'Sazan avı':level==='beginner'?'Surf':'Spin';if(place==='shore'&&level==='beginner')return {title:'Kıyıdan av için hazır setlere bakabilirsin.',description:'Kamış ve makineyi birlikte içeren kıyı setlerini incele. Seçmeden önce hedef balığını ve av yerini satıcıyla değerlendir.',href:route('catalog',{discipline:dis,category:'Hazır Setler'}),label:'Kıyı setlerini gör'};return {title:dis+' ekipmanlarından başlayabilirsin.',description:level==='beginner'?'Av yerine uygun ekipman grubunu seç. Birbirine uyumlu kamış ve makine için seçimden önce satıcıdan destek alabilirsin.':'İhtiyacın olan ekipman grubunu seçerek ürünleri daraltabilirsin.',href:route('discipline',{name:dis}),label:'Ekipmanları gör'}}

function filterErrors(data,validity={}){let min=Number(data.min||0),max=data.max?Number(data.max):Infinity,numberBad=validity.badMin||validity.badMax||!Number.isFinite(min)||(data.max&&!Number.isFinite(max));return {price:numberBad?'Geçerli bir fiyat yaz.':min<0||max<0?'Fiyat 0’dan küçük olamaz.':min>max?'En az fiyat, en fazla fiyattan büyük olamaz.':'',date:data.dateStart&&data.dateEnd&&data.dateStart>data.dateEnd?'Başlangıç tarihi, bitiş tarihinden sonra olamaz.':''}}

let menuReturnHash='#home';
function updateMenuControl(name){let button=$('.menu-button');if(!button)return;let open=!!$('#navigation-drawer')?.open;button.classList.toggle('is-open',open);button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Menüyü kapat':'Menüyü aç');button.href='#menu';let label=$('.menu-label',button);if(label)label.textContent=open?'Kapat':'Menü'}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&current().name==='menu'&&!e.altKey&&!e.ctrlKey){e.preventDefault();location.hash=menuReturnHash}});
